B.aea=new A.bg("N\u1ebfu \u0111\u1ed9 t\u01b0\u01a1ng \u0111\u1ed3ng ch\u01b0a \u0111\u1ee7 cao, h\u1ec7 th\u1ed1ng s\u1ebd \u0111\u1ec1 ngh\u1ecb x\xe1c nh\u1eadn ho\u1eb7c khuy\u1ebfn ngh\u1ecb qu\xe9t m\xe3 QR c\u1ea1nh hi\u1ec7n v\u1eadt.",B.G,null)
B.aeb=new A.bg("Ch\u01b0a c\xf3 tuy\u1ebfn \u0111\xe3 xu\u1ea5t b\u1ea3n ph\xf9 h\u1ee3p.",B.G,null)
B.aec=new A.bg("Ch\u01b0a c\xf3 y\xeau c\u1ea7u thanh to\xe1n.",B.G,null)
B.aed=new A.bg("Ch\u1ec9 chia s\u1ebb m\xe3 v\u1edbi ng\u01b0\u1eddi c\xf9ng nh\xf3m. T\u1ea1o m\xe3 m\u1edbi s\u1ebd thay th\u1ebf m\xe3 c\u0169; th\xe0nh vi\xean nh\u1eadp m\xe3 trong m\u1ee5c D\u1ecbch v\u1ee5 c\u1ee7a t\xf4i.",B.G,null)
B.aee=new A.bg("Hi\u1ec7n v\u1eadt ch\u01b0a c\xf3 b\u1ea3n thuy\u1ebft minh \u0111\u01b0\u1ee3c xu\u1ea5t b\u1ea3n.",B.G,null)
B.aef=new A.bg("C\xe1c b\u1ea3o t\xe0ng kh\xe1c s\u1ebd xu\u1ea5t hi\u1ec7n khi \u0111\u01b0\u1ee3c c\xf4ng khai tr\xean h\u1ec7 th\u1ed1ng.",B.G,null)
